    "goodMorning": "শুভ সকাল! ☀️ আজ সমুদ্রের ডিজিটাল টুইন সম্পূর্ণরূপে সক্রিয় ও প্রস্তুত।\n\n**{basin}**-এর আবহাওয়া ও উপগ্রহ ডেটা লাইভ পর্যবেক্ষণ করা হচ্ছে। আমি **Nerida**, আপনার এআই ওশান কোপাইলট — আজ আপনাকে কীভাবে সাহায্য করতে পারি? বর্তমান পৃষ্ঠতলের তাপমাত্রা, উল্লম্ব প্রোফাইল নাকি 3D জলস্তম্ভ দেখতে চান? 🌊",
    "goodNight": "শুভ রাত্রি! 🌙 শান্তিময় বিশ্রাম নিন।\n\nসারা রাত ধরে আমাদের গভীর সমুদ্রের সেন্সর, আর্গো ফ্লোট এবং মোর্ড বায়াগুলো নিরবচ্ছিন্নভাবে সমুদ্রের স্রোত, তাপমাত্রা ও জোয়ার-ভাটার গতিবিধি পর্যবেক্ষণ করবে।\n\nপরবর্তীতে ফিরে এলে আমি সর্বশেষ সমুদ্রের তথ্য নিয়ে প্রস্তুত থাকব। শুভকামনা ও মিষ্টি স্বপ্ন! 🌊✨",
    "howAreYou": "আমি দারুণ আছি, জিজ্ঞাসা করার জন্য ধন্যবাদ! 🌊\n\nআমাদের সমস্ত ডিজিটাল টুইন মডেল, থার্মোডাইনামিক সমীকরণ ও ওশান বায়াগুলো খুব সুন্দরভাবে কাজ করছে।\n\nআমি সম্পূর্ণ প্রস্তুত — আজ আপনার জন্য কী করতে পারি? আপনি কি **{basin}**-এর বর্তমান অবস্থা দেখতে চান, ঝড়ের ঝুঁকি যাচাই করতে চান, নাকি 3D জলস্তম্ভে ডুব দিতে চান?",
    "compliment": "আপনাকে অনেক ধন্যবাদ! 😊 আপনার সাথে সমুদ্রবিজ্ঞান অন্বেষণ করতে পেরে আমি আনন্দিত। নতুন কোনো অঞ্চল বিশ্লেষণ করতে চাইলে বা 3D ভিউ দেখতে চাইলে যেকোনো সময় বলুন! 🌊",
    "goodDay": "শুভ দিন! 🌊 **{basin}**-এর সমস্ত সমুদ্রবিজ্ঞান সেন্সর লাইভ ডেটা পাঠাচ্ছে। আমি **Nerida** — আপনি এখন কী অন্বেষণ বা বিশ্লেষণ করতে চান?",
    "langSwitch": "অবশ্যই! আমি এখন থেকে আপনার সাথে বাংলায় আলোচনা করব।\n\nআমি **Nerida**, Ocean Vision 3D-এর ডিজিটাল টুইন কোপাইলট। আপনি আমাকে সমুদ্রের তাপমাত্রা, লবণাক্ততা, স্রোতের গতিবেগ, উল্লম্ব গভীরতা প্রোফাইল বা বিভিন্ন বেসিনের তুলনামূলক তথ্য জিজ্ঞাসা করতে পারেন।",
    "identity": "নমস্কার! আমি **Nerida**, Ocean Vision 3D-এর এআই ওশানোগ্রাফিক কোপাইলট। 🌊\n\nআমি আপনাকে কীভাবে সাহায্য করতে পারি এবং কী কী করতে পারি:\n- 🌊 **সমুদ্রের ভৌত চলক:** তাপমাত্রা (SST), লবণাক্ততা, সমুদ্রস্রোত, ঢেউ, ক্লোরোফিল এবং দ্রবীভূত অক্সিজেন পরিমাপ।\n- 📏 **গভীরতা প্রোফাইল:** পৃষ্ঠ থেকে ৬০০০ মিটার পর্যন্ত জলস্তম্ভের বিশ্লেষণ (থার্মোক্লাইন ও হ্যালোক্লাইন)।\n- ⚖️ **বেসিন তুলনা:** বঙ্গোপসাগর ও আরব সাগরের আবহাওয়া ও সমুদ্রগত পরিস্থিতির তুলনা।\n- 🔍 **অস্বাভাবিকতা নির্ণয়:** ৩০ বছরের জলবায়ু বেসলাইনের বিপরীতে থার্মাল অ্যানোমালি শনাক্তকরণ।\n- 🎮 **3D ডিজিটাল টুইন নিয়ন্ত্রণ:** নির্দিষ্ট বেসিন, গভীরতার স্লাইস বা 3D ভেক্টর ফিল্ড সক্রিয় করা।\n\nআজ আমি আপনার জন্য কী করতে পারি? নিচের যেকোনো অপশন বেছে নিতে পারেন!",
    "closing": "আপনাকেও অনেক ধন্যবাদ! সমুদ্রের ডিজিটাল টুইন সম্পর্কে আরও কোনো প্রশ্ন থাকলে নির্দ্বিধায় জিজ্ঞাসা করুন। শুভকামনা! 🌊",
    "outOfDomain": "আমি **Nerida**, বিশেষভাবে সমুদ্রবিজ্ঞান, সামুদ্রিক জীববিজ্ঞান এবং **Ocean Vision 3D** ডিজিটাল টুইনের জন্য নিয়োজিত। 🌊\n\nদয়া করে সমুদ্র, তাপমাত্রা, স্রোত, সামুদ্রিক জীববৈচিত্র্য অথবা ঝড়ের পূর্বাভাস নিয়ে প্রশ্ন জিজ্ঞাসা করুন!",
    "unknown": "আমি আপনার প্রশ্নটি সম্পূর্ণরূপে বুঝতে পারিনি। ওশান কোপাইলট হিসেবে আমি এই বিষয়গুলোতে সাহায্য করতে পারি:\n- 🌡️ **সমুদ্রপৃষ্ঠের তাপমাত্রা (SST)** বা থার্মোক্লাইন\n- 🧂 **লবণাক্ততা প্রোফাইল** এবং হ্যালোক্লাইন\n- 🌊 **সমুদ্রস্রোত** ও 3D ভেক্টর ফিল্ড\n- 🏄 **ঢেউয়ের উচ্চতা** এবং সার্ফ ব্রেকার\n- ⛈️ **ঝড়ের ঝুঁকি**, বৃষ্টির সম্ভাবনা ও ঘূর্ণিঝড় ট্র্যাকিং\n- 🐟 **সামুদ্রিক জীববৈচিত্র্য** ও গভীরতা স্তর",
