    "welcome": "নমস্কাৰ! মই **Nerida**, Ocean Vision 3D ৰ AI সাগৰ ক'পাইলট। বৰ্তমান মই **{basin}** নিৰীক্ষণ কৰি আছোঁ।\n\nআজি মই আপোনাক কেনেকৈ সহায় কৰিব পাৰোঁ? সাগৰ পৃষ্ঠৰ উষ্ণতা, লৱণাক্ততা, সোঁত বা 3D দৃশ্য চাব বিচাৰে নেকি? 🌊",
    "goodMorning": "শুভ প্ৰভাত! ☀️ আজি সাগৰীয় ডিজিটেল টুইন সম্পূৰ্ণৰূপে সক্ৰিয় আৰু সাজু।\n\n**{basin}** ৰ বাবে সকলো ছেন্সৰ আৰু উপগ্ৰহ তথ্য লাইভ হৈ আছে। মই **Nerida** — আজি আপোনাৰ বাবে মই কি কৰিব পাৰোঁ? 🌊",
    "goodNight": "শুভ ৰাত্ৰি! 🌙 আৰামেৰে জিৰণি লওক।\n\nৰাতিটো আমাৰ ছেন্সৰ আৰু আৰ্গো ফ্ল'টসমূহে সাগৰীয় সোঁত আৰু উষ্ণতা নিৰন্তৰ নিৰীক্ষণ কৰি থাকিব। মিঠা সপোন! 🌊✨",
    "howAreYou": "মই বহুত ভাল আছোঁ, সোধাৰ বাবে ধন্যবাদ! 🌊\n\nসকলো ডিজিটেল টুইন মডেল আৰু TEOS-10 সমীকৰণ সুন্দৰভাৱে চলি আছে। আজি আপুনি কি জানিব বিচাৰে?",
