    "goodMorning": "સુપ્રભાત! ☀️ આજે મહાસાગર સંપૂર્ણપણે સક્રિય અને સજ્જ છે.\n\n**{basin}** માટે તમામ સેન્સર્સ અને સેટેલાઇટ ડેટા લાઇવ છે. હું **નેરિડા** છું — આજે આપના માટે હું શું કરી શકું? 🌊",
