    "identity": "નમસ્તે! હું **નેરિડા (Nerida)** છું, Ocean Vision 3D ની આપની AI ઓશનોગ્રાફિક કોપાયલટ. 🌊\n\n- 🌊 **ભૌતિક પરિમાણો:** સપાટીનું તાપમાન (SST), ક્ષારતા, પ્રવાહો, મોજાં, ઓક્સિજન.\n- 📏 **ઊંડાઈ પ્રોફાઇલ:** સપાટીથી 6000 મીટર સુધીનું સંપૂર્ણ જળ સ્તંભ વિશ્લેષણ.\n- ⚖️ **બેસિન સરખામણી:** બંગાળની ખાડી અને અરબી સમુદ્ર વચ્ચે સરખામણી.\n- 🔍 **વિસંગતતા વિશ્લેષણ:** 30 વર્ષના આબોહવા આધાર સામે મરીન હીટવેવની ઓળખ.\n- 🎮 **3D નિયંત્રણ:** 3D દ્રશ્ય અને વિવિધ ઊંડાઈ સ્લાઇસ નિયંત્રિત કરવી.",
