    "goodNight": "शुभ रात्री! 🌙 शांत झोप घ्या.\n\nरात्रभर आमचे सेन्सर्स आणि आर्गो फ्लोट्स महासागरीय प्रवाह आणि तापमानावर बारीक लक्ष ठेवतील. गोड स्वप्ने! 🌊✨",
