    "langSwitch": "समजले! आतापासून मी आपल्याशी मराठीत संवाद साधेन.\n\nमी **नेरिडा**, Ocean Vision 3D डिजिटल ट्विन कोपायलट. मला समुद्राचे तापमान, क्षारता, प्रवाह किंवा खोली प्रोफाइलबद्दल विचारा.",
    "identity": "नमस्कार! मी **नेरिडा (Nerida)**, Ocean Vision 3D ची आपली AI ओशनोग्राफिक कोपायलट. 🌊\n\n- 🌊 **भौतिक पॅरामीटर्स:** पृष्ठभाग तापमान (SST), क्षारता, प्रवाह, लाटा, ऑक्सिजन.\n- 📏 **खोली प्रोफाइल:** पृष्ठभागापासून ६००० मीटरपर्यंत पाण्याचे संपूर्ण विश्लेषण.\n- ⚖️ **बेसिन तुलना:** बंगालचा उपसागर आणि अरबी समुद्राची तुलना.\n- 🔍 **विसंगती विश्लेषण:** ३० वर्षांच्या हवामान आधारावर मरीन हीटवेव्ह ओळखणे.\n- 🎮 **3D नियंत्रण:** 3D व्ह्यू आणि विविध खोली स्लाइस नियंत्रित करणे.",
