    "compliment": "بہت بہت شکریہ! 😊 آپ کے ساتھ سمندر کی تحقیق کرنا میرے لیے خوشی کا باعث ہے۔ کسی نئے طاس یا 3D منظر کے بارے میں جب چاہیں پوچھیں! 🌊",
