    "langSwitch": "Understood! Communicating in سنڌي (Sindhi).\n\nI am **Nerida**, your Ocean Vision 3D digital-twin copilot.",
    "identity": "السلام علیکم! میں **نیریڈا (Nerida)** ہوں، Ocean Vision 3D کے لیے آپ کی AI بحری سائنس کوپائلٹ۔ 🌊\n\n- 🌊 **طبیعی پیمائش:** سطح کا درجہ حرارت (SST)، نمکیات، روئیں، لہریں، آکسیجن۔\n- 📏 **گہرائی کا پروفائل:** سطح سے 6000 میٹر تک پانی کے کالم کا مکمل تجزیہ۔\n- ⚖️ **طاس کا موازنہ:** خلیج بنگال اور بحیرہ عرب کے درمیان موازنہ۔\n- 🔍 **انحراف کا تجزیہ:** 30 سالہ موسمیاتی بیس لائن کے مقابلے میں تھرمل انحراف کی شناخت۔\n- 🎮 **3D کنٹرول:** 3D منظر اور گہرائی کے سلائسز کو کنٹرول کرنا۔",
