/**
 * Returns localized lexicon object for any language code, falling back gracefully.
 */
export function getCopilotLexicon(lang = 'en') {
  const code = (lang || 'en').toLowerCase().split('-')[0];
  return COPILOT_LEXICON[code] || COPILOT_LEXICON['en'];
}

/**
 * Formats full meteorological storm & cyclone prediction in the selected language.
 */
export function formatStormPrediction(predictionData, lang = 'en') {
  const L = getCopilotLexicon(lang);
  const loc = predictionData.location || 'Target Station';
  const coords = predictionData.coordinates || '15.297° N, 87.860° E';
  const basin = predictionData.basin || 'Ocean Sector';
  const storm = predictionData.activeStorm || {};
  const outlook = predictionData.threeDayOutlook || [];
  const beachList = predictionData.beachForecasts || [];

  const locHeader = predictionData.isImplicitLocation
    ? L.currLocHeader.replace('{location}', loc).replace('{coords}', coords)
    : L.locHeader.replace('{location}', loc).replace('{coords}', coords).replace('{basin}', basin);

  const threatLine = L.stormRisk
    .replace('{threat}', predictionData.threatLevel || 'LOW')
    .replace('{prob}', predictionData.stormProbability ?? 30);

  const stormLine = `- **${L.activeSystem}:** **${storm.name || 'Nominal Flow'}** (*${storm.category || 'Standard Maritime Activity'}*)`;
  const windLine = `- **${L.windAndPressure}:** \`${predictionData.windSpeedKmH || '24 km/h'}\` | ${L.baroPressure || 'Pressure'}: \`${predictionData.pressure || '1010 hPa'}\``;
  const rainLine = `- **${L.precipProb}:** **\`${predictionData.rainProbability ?? 35}%\`** (${storm.rainfallForecast || 'Passing showers'})`;
  const waveLine = `- **${L.waveSurge}:** \`${predictionData.waveHeight || '1.6m'}\` (${L.surge || 'Surge'}: \`${storm.surge || '0.5m'}\`)`;
  const sstLine = `- **${L.thermalFuel}:** \`${predictionData.seaSurfaceTemperature || '29.0°C'}\` (*${predictionData.cyclogenesisPotential || 'Nominal'}*)`;

  let outlookBlock = '';
  if (outlook.length >= 3) {
    outlookBlock = `\n\n${L.threeDayOutlook}\n` +
      `- **${L.today}:** ${outlook[0].condition} | ${L.rain}: \`${outlook[0].rainProbability}%\` | ${L.wind}: \`${outlook[0].windSpeedKmH} km/h\` | ${L.swell}: \`${outlook[0].waveHeight}\`\n` +
      `- **${L.tomorrow}:** ${outlook[1].condition} | ${L.rain}: \`${outlook[1].rainProbability}%\` | ${L.wind}: \`${outlook[1].windSpeedKmH} km/h\`\n` +
      `- **${L.day3}:** ${outlook[2].condition} | ${L.rain}: \`${outlook[2].rainProbability}%\``;
  }

  let beachBlock = '';
  if (beachList.length > 0) {
    beachBlock = `\n\n${L.beachAlerts}\n` + beachList.map(b => 
      `- **${b.beachName}** (${b.location}): **${b.safetyFlag}** — ${L.rain}: \`${b.rainProbability}%\`, ${L.breakers}: \`${b.surfWaveHeight}m\``
    ).join('\n');
  }

  return `${locHeader}\n\n${threatLine}\n${stormLine}\n${windLine}\n${rainLine}\n${waveLine}\n${sstLine}${outlookBlock}${beachBlock}`;
}

/**
 * Formats holistic physical ocean state in the selected language.
 */
export function formatGeneralConditions(region, locName, lang = 'en') {
  const L = getCopilotLexicon(lang);
  const name = locName || region.name || 'Ocean Station';
  const coords = region.coords || '15.297° N, 87.860° E';

  const title = L.currentCondTitle.replace('{location}', name).replace('{coords}', coords);
  const sst = `- 🌡️ **${L.sstLabel}:** **\`${region.sst}°C\`**`;
  const sal = `- 🧂 **${L.salinityLabel}:** **\`${region.salinity} PSU\`**`;
  const cur = `- 🌊 **${L.currentsLabel}:** **\`${region.currentSpeed} m/s\`**`;
  const wav = `- 🏄 **${L.waveLabel}:** **\`${region.waveHeight}m\`**`;
  const wind = `- 💨 **${L.windAndPressure}:** \`${region.windSpeedKmH || 24} km/h\` (\`${region.pressure || 1010} hPa\`)`;
  const oxy = `- 🧪 **${L.oxygenLabel}:** \`${region.oxygen || 6.8} mg/L\``;
  const chl = `- 🌿 **${L.chlorophyllLabel}:** \`${region.chlorophyll || 1.2} mg/m³\``;
  const storm = `- ⛈️ **${L.activeSystem}:** **${region.activeStorm?.name || 'Nominal Flow'}** (\`${region.rainProbability || 35}%\` ${L.rain || 'rain'})`;

  return `${title}\n\n${sst}\n${sal}\n${cur}\n${wav}\n${wind}\n${oxy}\n${chl}\n${storm}`;
}

/**
 * Formats conversational responses in the selected language.
 */
export function formatConversational(type, basinName = 'Bay of Bengal', lang = 'en') {
  const L = getCopilotLexicon(lang);
  const bName = basinName || 'Bay of Bengal';
  const template = L[type] || L.welcome;
  return template.replace(/{basin}/g, bName);
}

/**
 * Formats marine biology and ecological zones in the selected language.
 */
export function formatMarineBiology(basinName, depthMeters, depthZone, depthDescription, zoneOrganisms, basinFauna, lang = 'en') {
  const L = getCopilotLexicon(lang);
  const header = L.bioHeader.replace('{basin}', basinName).replace('{depth}', depthMeters);
  return `${header}\n\n` +
    `🌊 **${L.depthZone}:** ${depthZone}\n` +
    `- *${L.ecoCondition}:* ${depthDescription}\n` +
    `- **${L.keyOrganisms}:** ${zoneOrganisms}\n\n` +
    `🌐 **${L.basinHighlights}:**\n${basinFauna}\n\n` +
    `${L.ecoCaveat}`;
}

/**
 * Formats single physical parameter telemetry in the selected language.
 */
export function formatOceanQuery(data, explanation = '', locDisplay = null, lang = 'en') {
  const L = getCopilotLexicon(lang);
  const loc = locDisplay || data.location || 'Ocean Station';
  const paramKey = data.parameter || 'sst';
  const paramName = L[paramKey + 'Label'] || data.parameterName || paramKey;
  const unit = data.unit || '';
  const header = L.queryHeader
    .replace('{basin}', loc)
    .replace('{depth}', data.depth)
    .replace('{param}', paramName)
    .replace('{value}', data.value)
    .replace('{unit}', unit);

  const valLine = `- **${L.currentVal || 'Observed Value'}:** \`${data.value} ${unit}\``;
  const coordLine = data.coordinates ? `- **Coordinates:** \`${data.coordinates}\`` : '';
  const srcLine = `- **${L.obsSource}:** ${data.source || 'In-situ Sensors'}`;
  const qcLine = `- **${L.qcStatus}:** \`${L.qcPassed}\``;
  const explBlock = explanation ? `\n\n💡 **Scientific Oceanographic Mechanism:**\n${explanation}` : '';

  return `${header}\n\n${valLine}\n${coordLine ? coordLine + '\n' : ''}${srcLine}\n${qcLine}${explBlock}`;
}

/**
 * Formats vertical water column profile in the selected language.
 */
export function formatProfile(profileData, lang = 'en') {
  const L = getCopilotLexicon(lang);
  const loc = profileData.location || 'Ocean Basin';
  const paramKey = profileData.parameter || 'sst';
  const paramName = L[paramKey + 'Label'] || profileData.parameterName || 'Temperature';
  const unit = profileData.unit || '';
  const depths = profileData.depths || [0, 50, 100, 200, 500, 1000, 2000];
  const values = profileData.values || [];

  const surfaceVal = values[0] !== undefined ? `${values[0]} ${unit}` : 'N/A';
  const midIdx = depths.indexOf(500) !== -1 ? depths.indexOf(500) : (depths.length > 4 ? 4 : 0);
  const midVal = values[midIdx] !== undefined ? `${values[midIdx]} ${unit}` : 'N/A';
  const deepVal = values[values.length - 1] !== undefined ? `${values[values.length - 1]} ${unit}` : 'N/A';

  return `📊 **${loc}** — **${paramName}** (0m - 2000m):\n\n` +
    `- **${L.today || 'Surface'} (0m):** \`${surfaceVal}\`\n` +
    `- **Intermediate (500m):** \`${midVal}\`\n` +
    `- **Deep Layer (2000m):** \`${deepVal}\`\n\n` +
    `💡 **Pycnocline Boundaries:**\n` +
    `- **Thermocline:** ${profileData.thermoclineDepth || '100m'}\n` +
    `- **Halocline / Barrier Layer:** ${profileData.haloclineDepth || '120m'}`;
}

/**
 * Formats multi-basin comparison in the selected language.
 */
export function formatComparison(compData, depth = 0, lang = 'en') {
  const L = getCopilotLexicon(lang);
  const paramKey = compData.parameter || 'sst';
  const paramName = L[paramKey + 'Label'] || compData.parameterName || 'Parameter';
  const header = L.compHeader
    .replace('{basin1}', compData.basin1.name)
    .replace('{basin2}', compData.basin2.name)
    .replace('{depth}', depth)
    .replace('{param}', paramName);

  const b1 = `- **${compData.basin1.name}:** \`${compData.basin1.value} ${compData.unit}\``;
  const b2 = `- **${compData.basin2.name}:** \`${compData.basin2.value} ${compData.unit}\``;
  const dLine = `- **${L.difference}:** \`${compData.difference} ${compData.unit}\``;
  const hLine = `- **${L.higherBasin}:** **${compData.higherBasin}**`;
  const rBlock = `\n\n🔬 **${L.scientificRationale}:**\n${compData.scientificRationale}`;

  return `${header}\n\n${b1}\n${b2}\n${dLine}\n${hLine}${rBlock}`;
}

/**
 * Formats anomaly diagnostic in the selected language.
 */
export function formatAnalysis(anomalyData, lang = 'en') {
  const L = getCopilotLexicon(lang);
  const paramKey = anomalyData.parameter || 'sst';
  const paramName = L[paramKey + 'Label'] || anomalyData.parameterName || 'Parameter';
  const detected = L.anomalyDetected
    .replace('{basin}', anomalyData.location)
    .replace('{depth}', anomalyData.depth)
    .replace('{param}', paramName)
    .replace('{severity}', anomalyData.severity);

  return `${L.anomalyHeader}\n\n${detected}\n\n` +
    `- **${L.currentVal}:** \`${anomalyData.currentValue} ${anomalyData.unit}\`\n` +
    `- **${L.baselineVal}:** \`${anomalyData.baseline} ${anomalyData.unit}\`\n` +
    `- **${L.deviation}:** \`${anomalyData.anomaly} ${anomalyData.unit}\`\n` +
    `- **${L.severity}:** \`${anomalyData.severity}\`\n` +
    `- **${L.confidence}:** \`${anomalyData.confidence}\`\n\n` +
    `💡 **Diagnostic Overview:**\n${anomalyData.diagnosticSummary}`;
}

/**
 * Formats 3D Viewport mutations in the selected language.
 */
export function formatViewCommand(changes = [], lang = 'en') {
  const L = getCopilotLexicon(lang);
  const changeText = changes.join(', ');
  return `${L.viewUpdated}\n\n${changeText}`;
}

/**
 * Formats out-of-domain rejection in the selected language.
 */
export function formatOutOfDomain(lang = 'en') {
  return getCopilotLexicon(lang).outOfDomain;
}

/**
 * Formats unknown/clarification query in the selected language.
 */
export function formatUnknown(basinName = 'Bay of Bengal', lang = 'en') {
  const L = getCopilotLexicon(lang);
  const template = L.unknown || '';
  return template.replace(/{basin}/g, basinName);
}

/**
 * Returns localized suggestion chips for any intent in the selected language.
 */
export function getLocalizedSuggestions(intentType, basinName = 'Bay of Bengal', lang = 'en') {
  const L = getCopilotLexicon(lang);
  const bName = basinName || 'Bay of Bengal';
  const S = L.suggestions || {};
  return [
    (S.conditions || 'Explain current conditions in {basin}').replace('{basin}', bName),
    S.profile || 'Show temperature profile',
    S.compare || 'Compare Arabian Sea and Bay of Bengal',
    (S.storm || 'Assess storm risk in {basin}').replace('{basin}', bName)
  ];
}

/**
 * Returns localized quick action buttons for CopilotQuickActions.jsx.
 */
export function getLocalizedQuickActions(lang = 'en') {
  const L = getCopilotLexicon(lang);
  const S = L.suggestions || {};
  return [
    { id: 'conditions', label: (S.conditions || 'Conditions').replace('{basin}', '').trim(), prompt: 'Explain current oceanographic and meteorological conditions for this basin in detail.' },
    { id: 'storm_risk', label: (S.storm || 'Storm Risk').replace('{basin}', '').trim(), prompt: 'Assess maritime storm threat, wave surge, and vessel navigation safety.' },
    { id: 'profile', label: S.profile || 'Temperature Profile', prompt: 'Show the vertical temperature stratification profile.' },
    { id: 'compare', label: S.compare || 'Compare Basins', prompt: 'Compare Bay of Bengal versus Arabian Sea in salinity, stratification, and cyclogenesis.' },
    { id: 'vectors', label: S.vectors || 'Current Vectors', prompt: 'Show current vector field in 3D.' },
    { id: 'marineLife', label: (S.marineLife || 'Marine Life').replace('{basin}', '').trim(), prompt: 'What marine life is found in this basin?' }
  ];
}
